package org.apache.commons.math3.geometry.euclidean.threed;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.apache.commons.math3.geometry.euclidean.oned.Interval;
import org.apache.commons.math3.geometry.euclidean.oned.IntervalsSet;
import org.apache.commons.math3.geometry.euclidean.oned.Vector1D;
import org.apache.commons.math3.geometry.euclidean.threed.digest.Vector3D;
import org.apache.commons.math3.geometry.euclidean.threed.line.IntervalsSet;
import org.apache.commons.math3.geometry.euclidean.threed.line.Line;
import org.apache.commons.math3.geometry.euclidean.threed.line.Segment;
import org.apache.commons.math3.geometry.partitioning.Region.Location;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Unit tests for SubLine#intersection
 */
public class SubLine_intersection_TriageGen0Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testIntersection_WithEndPoints_InsideBoth() {
        // Line 1: x-axis from (0,0,0) to (10,0,0)
        SubLine subLine1 = new SubLine(new Vector3D(0, 0, 0), new Vector3D(10, 0, 0));
        // Line 2: y-axis from (5,-5,0) to (5,5,0). Intersection at (5,0,0) which is INSIDE both.
        SubLine subLine2 = new SubLine(new Vector3D(5, -5, 0), new Vector3D(5, 5, 0));

        Vector3D result = subLine1.intersection(subLine2, true);

        assertNotNull("Intersection should not be null", result);
        assertEquals(5.0, result.getX(), EPSILON);
        assertEquals(0.0, result.getY(), EPSILON);
        assertEquals(0.0, result.getZ(), EPSILON);
    }

    @Test
    public void testIntersection_WithEndPoints_OnBoundary() {
        // Line 1: x-axis from (0,0,0) to (10,0,0)
        SubLine subLine1 = new SubLine(new Vector3D(0, 0, 0), new Vector3D(10, 0, 0));
        // Line 2: y-axis from (0,0,0) to (0,10,0). Intersection at (0,0,0) which is an ENDPOINT.
        SubLine subLine2 = new SubLine(new Vector3D(0, 0, 0), new Vector3D(0, 10, 0));

        // Case: includeEndPoints = true -> Should return the point
        Vector3D resultInclude = subLine1.intersection(subLine2, true);
        assertNotNull("Should include endpoint", resultInclude);
        assertEquals(0.0, resultInclude.getX(), EPSILON);
        assertEquals(0.0, resultInclude.getY(), EPSILON);

        // Case: includeEndPoints = false -> Should return null (since it's on the boundary, not strictly inside)
        Vector3D resultExclude = subLine1.intersection(subLine2, false);
        assertNull("Should exclude endpoint", resultExclude);
    }

    @Test
    public void testIntersection_WithoutEndPoints_InsideBoth() {
        // Line 1: x-axis (0,0,0) to (10,0,0)
        SubLine subLine1 = new SubLine(new Vector3D(0, 0, 0), new Vector3D(10, 0, 0));
        // Line 2: y-axis (5,-5,0) to (5,5,0). Intersection (5,0,0) is INSIDE.
        SubLine subLine2 = new SubLine(new Vector3D(5, -5, 0), new Vector3D(5, 5, 0));

        Vector3D result = subLine1.intersection(subLine2, false);

        assertNotNull("Intersection should be found inside", result);
        assertEquals(5.0, result.getX(), EPSILON);
    }

    @Test
    public void testIntersection_OutsideOneOrBoth() {
        // Line 1: x-axis (0,0,0) to (10,0,0)
        SubLine subLine1 = new SubLine(new Vector3D(0, 0, 0), new Vector3D(10, 0, 0));
        // Line 2: y-axis (15,-5,0) to (15,5,0). Intersection at (15,0,0) which is OUTSIDE subLine1.
        SubLine subLine2 = new SubLine(new Vector3D(15, -5, 0), new Vector3D(15, 5, 0));

        // includeEndPoints = true
        assertNull("Should be null as it is outside", subLine1.intersection(subLine2, true));

        // includeEndPoints = false
        assertNull("Should be null as it is outside", subLine1.intersection(subLine2, false));
    }

    @Test
    public void testIntersection_NoInfiniteIntersection() {
        // Parallel lines
        SubLine subLine1 = new SubLine(new Vector3D(0, 0, 0), new Vector3D(10, 0, 0));
        SubLine subLine2 = new SubLine(new Vector3D(0, 1, 0), new Vector3D(10, 1, 0));

        // Note: line.intersection(subLine.line) might throw exception or return null/NaN depending on Math3 version
        // if lines are parallel. Assuming standard behavior where we test the logic flow.
        // If the implementation of line.intersection(line) throws exception for parallel lines, 
        // this test verifies that the method propagates it.
        try {
            subLine1.intersection(subLine2, true);
        } catch (Exception e) {
            // Expected if parallel lines don't have a single intersection point
        }
    }

    @Test
    public void testIntersection_BoundaryCase_OneInsideOneOutside() {
        // Line 1: x-axis (0,0,0) to (10,0,0)
        SubLine subLine1 = new SubLine(new Vector3D(0, 0, 0), new Vector3D(10, 0, 0));
        // Line 2: y-axis (11,-5,0) to (11,5,0). Intersection (11,0,0).
        // (11,0,0) is OUTSIDE subLine1.
        SubLine subLine2 = new SubLine(new Vector3D(11, -5, 0), new Vector3D(11, 5, 0));

        assertNull(subLine1.intersection(subLine2, true));
        assertNull(subLine1.intersection(subLine2, false));
    }
}
